#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <stdbool.h>

#include "constants.h"
#include "stats.h"

struct stats_table *stats;

/*
 * lookup an entry in the stats table
 * return it
 * create a new entry if not found
 */
struct stats_table *stats_entry(const char *n) {
	struct stats_table *s;
	struct stats_table *t;

	s = stats;
	while (s != NULL) {
		if (strcmp(s->name, n) == 0) {
			return s;
		}
		s = s->next;
	}
	/*
	 * if stat is not found, create a new one
	 * add to the start of the list
	 * it is easier than adding it at the end
	 */
	t = (struct stats_table *) malloc(sizeof(struct stats_table));
	t->name = strdup(n);
	t->value = 0;
	t->next = stats;
	stats = t;
	return t;
}

void incr_stat(const char *n) {
	struct stats_table *s;

	s = stats_entry(n);
	s->value += 1;
}

void decr_stat(const char *n) {
	struct stats_table *s;

	s = stats_entry(n);
	s->value -= 1;
}

void add_to_stat(const char *n, int i) {
	struct stats_table *s;

	s = stats_entry(n);
	s->value += i;
}

void set_stat(const char *n, int v) {
	struct stats_table *s;

	s = stats_entry(n);
	s->value = v;
}

int get_stat(const char *n) {
	struct stats_table *s;

	s = stats_entry(n);
	return s->value;
}

